import{_ as o,o as e,c as d,a2 as a}from"./chunks/framework.DMvgf4hZ.js";const m=JSON.parse('{"title":"插件开发","description":"","frontmatter":{"title":"插件开发"},"headers":[],"relativePath":"plugins/index.md","filePath":"plugins/index.md","lastUpdated":1794884041000}'),l={name:"plugins/index.md"};function s(r,t,n,i,c,h){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="插件开发" tabindex="-1">插件开发 <a class="header-anchor" href="#插件开发" aria-label="Permalink to &quot;插件开发&quot;">​</a></h1><p><strong>DEVELOPER GUIDE</strong>　工具 · 画布节点 · 技能</p><p>本文面向 Toonflow 插件开发者，介绍 tools、nodes、skill 的开发契约、最小示例、构建与安装流程。<strong>teams 当前处于测试阶段，尚未开放。</strong></p><p>示例依据当前仓库实现，在 Toonflow 的 Bun Workspaces 中开发。脚手架使用 <code>workspace:*</code> 引用；版本与依赖应跟随所开发的 Toonflow 版本。</p><blockquote><p><strong>阅读路线</strong>　首次开发先读「01 开发总览」，再按扩展类型进入 Tools、Nodes 或 Skill；完成后对照「06 交付前检查」。</p><p><strong>开放状态</strong>　Tools / Nodes / Skill 可开发；A2A Teams 暂未开放。</p></blockquote><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>你要解决的问题</th><th>一句话结论</th></tr></thead><tbody><tr><td><a href="./overview.html">01 · 开发总览</a></td><td>该做 tool、node 还是 skill？环境怎么搭、怎么装怎么调？</td><td>先选题再动手；<code>dev:plugins</code> 同步到 <code>data/</code>，构建与类型检查分开跑。</td></tr><tr><td><a href="./tools.html">02 · Tools 工具插件开发</a></td><td>给 Agent 增加搜索、文件、媒体等可调用能力。</td><td>Bun 服务端执行，产物 <code>&lt;toolName&gt;.tool.js</code>，可带 Vue 消息组件。</td></tr><tr><td><a href="./nodes.html">03 · Nodes 节点插件开发</a></td><td>给画布增加交互组件、端口与节点操作。</td><td>Vue 3 包，<code>defineOptions</code> 声明端口，<code>useNode</code> 取状态，产物 <code>&lt;nodeName&gt;.umd.js</code>。</td></tr><tr><td><a href="./skill.html">04 · Skill 技能插件开发</a></td><td>约定流程、方法、输出要求与参考资料。</td><td>只有 <code>SKILL.md</code> 与附属资料，不编译、不新增执行权限。</td></tr><tr><td><a href="./teams.html">05 · A2A Teams 团队插件</a></td><td>组织多 Agent 职责与协作。</td><td><strong>测试阶段，尚未开放</strong>，仅说明状态。</td></tr><tr><td><a href="./checklist.html">06 · 交付前检查</a></td><td>发布前要自查什么。</td><td>名称/导出/版本一致，从最终分发文件安装验证。</td></tr><tr><td><a href="./publish.html">07 · 发布插件</a></td><td>把插件交给用户。</td><td>直接上传到 Toonflow 插件市场，不需要向仓库提 PR。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">和「插件市场」页面的关系</p><p>站点另一处<a href="/toonflow/guide/plugin-market.html">插件市场</a>讲的是<strong>用户怎么装插件</strong>；「插件、技能与提供方」<a href="/toonflow/development/plugins.html">开发文档页面</a>讲的是<strong>安装契约与 <code>toonflow://install</code> 协议</strong>。本分组是从零写一个插件到发布的全流程开发指南。</p></div>',8)])])}const f=o(l,[["render",s]]);export{m as __pageData,f as default};
